from dataclasses import dataclass

@dataclass
class TranscriptionJobRequest:
    job_name: str
    audio_file_uri: str
    media_format: str  # e.g., "wav", "mp3", "flac"
    language_code: str # e.g., "en-US", "es-ES"

@dataclass
class TranscriptionJobResult:
    job_name: str
    status: str
    transcript_file_uri: str | None = None
    failure_reason: str | None = None

import boto3
from speech_client import get_transcribe_client
from speech_models import TranscriptionJobResult
import time

def poll_transcription_job(job_name: str, timeout_seconds: int = 600, poll_interval_seconds: int = 10) -> TranscriptionJobResult:
    transcribe_client = get_transcribe_client()
    start_time = time.time()

    while time.time() - start_time < timeout_seconds:
        response = transcribe_client.get_transcription_job(TranscriptionJobName=job_name)
        job_status = response['TranscriptionJob']['TranscriptionJobStatus']

        if job_status == 'COMPLETED':
            transcript_uri = response['TranscriptionJob']['Transcript']['TranscriptFileUri']
            return TranscriptionJobResult(job_name=job_name, status=job_status, transcript_file_uri=transcript_uri)
        elif job_status == 'FAILED':
            failure_reason = response['TranscriptionJob'].get('FailureReason', 'Unknown reason')
            return TranscriptionJobResult(job_name=job_name, status=job_status, failure_reason=failure_reason)

        print(f"Transcription job {job_name} is {job_status}. Polling again in {poll_interval_seconds} seconds...")
        time.sleep(poll_interval_seconds)

    return TranscriptionJobResult(job_name=job_name, status="TIMEOUT", failure_reason="Job timed out")

if __name__ == '__main__':
    # Replace with an actual job name to poll
    job_to_poll = "my-batch-transcription-job-1"
    print(f"Polling transcription job: {job_to_poll}")
    result = poll_transcription_job(job_to_poll)

    if result.status == "COMPLETED":
        print(f"Job {result.job_name} completed. Transcript URI: {result.transcript_file_uri}")
    elif result.status == "FAILED":
        print(f"Job {result.job_name} failed. Reason: {result.failure_reason}")
    elif result.status == "TIMEOUT":
        print(f"Job {result.job_name} timed out. Reason: {result.failure_reason}")
    else:
        print(f"Job {result.job_name} status: {result.status}")

import boto3
import requests
import json

def get_timestamped_transcript(transcript_uri: str) -> dict:
    # Download the transcript JSON from the S3 URI
    response = requests.get(transcript_uri)
    response.raise_for_status()  # Raise an exception for HTTP errors
    transcript_data = json.loads(response.text)

    # Extract relevant information including word-level timestamps
    # The exact structure depends on the Transcribe output, which usually includes
    # 'results' and 'items' for detailed word-level data.

    # This is a simplified example. A full implementation would parse
    # the 'items' array from the transcript_data['results'] for detailed timestamps.

    # For demonstration, we'll return a simplified structure or the raw data.

    # Example of extracting items with timestamps:
    word_timestamps = []
    if 'results' in transcript_data and 'items' in transcript_data['results']:
        for item in transcript_data['results']['items']:
            if item['type'] == 'pronunciation':
                word_timestamps.append({
                    'word': item['alternatives'][0]['content'],
                    'start_time': item['start_time'],
                    'end_time': item['end_time']
                })

    return {
        "full_transcript": transcript_data['results']['transcripts'][0]['transcript'] if 'results' in transcript_data and 'transcripts' in transcript_data['results'] else "",
        "word_timestamps": word_timestamps
    }

if __name__ == '__main__':
    # Replace with an actual transcript URI from a completed AWS Transcribe job
    example_transcript_uri = "https://s3.us-east-1.amazonaws.com/aws-transcribe-us-east-1-prod/your-job-id/your-job-id.json"
    try:
        transcript_with_timestamps = get_timestamped_transcript(example_transcript_uri)
        print("Full Transcript:")
        print(transcript_with_timestamps["full_transcript"])
        print("\nWord Timestamps:")
        for item in transcript_with_timestamps["word_timestamps"]:
            print(f"  Word: {item['word']}, Start: {item['start_time']}, End: {item['end_time']}")
    except Exception as e:
        print(f"Error retrieving or parsing timestamped transcript: {e}")

import boto3
import os

def get_translate_client():
    # Initialize AWS Translate client
    return boto3.client("translate")

def translate_text(text: str, source_language_code: str, target_language_code: str) -> str:
    translate_client = get_translate_client()
    response = translate_client.translate_text(
        Text=text,
        SourceLanguageCode=source_language_code,
        TargetLanguageCode=target_language_code
    )
    return response['TranslatedText']

if __name__ == '__main__':
    example_text = "Hello, how are you today?"
    source_lang = "en"
    target_lang = "es"

    try:
        translated_text = translate_text(example_text, source_lang, target_lang)
        print(f"Original text ({source_lang}): {example_text}")
        print(f"Translated text ({target_lang}): {translated_text}")
    except Exception as e:
        print(f"Error translating text: {e}")
